221→export class WaitingRoomView implements OnInit, OnDestroy {
222→  private readonly route = inject(ActivatedRoute);
223→  private readonly router = inject(Router);
224→  private readonly http = inject(HttpClient);
225→  private readonly api = inject(WaitingRoomApiService);
226→  private readonly ws = inject(ExerciseWsService);
227→  private readonly exerciseApi = inject(ExerciseApiService);
228→  private readonly scenarioApi = inject(ScenarioApiService);
229→  private sub: Subscription | null = null;
230→
231→  protected readonly browseMode = signal(false);
232→  protected readonly joinableExercises = signal<JoinableExercise[]>([]);
233→  protected readonly exerciseId = signal(0);
234→  protected readonly participantId = signal("");
235→  protected readonly participants = signal<ParticipantResponse[]>([]);
236→  protected readonly gameMode = signal("classic");
237→  protected readonly playerCountMode = signal<PlayerCountMode>("full");
238→  protected readonly scenarioRoles = signal<RoleDef[]>([]);
239→  protected readonly requiresGm = signal(false);
240→  protected readonly displayName = signal("");
241→  protected readonly joining = signal(false);
242→
243→  protected readonly isSimpleCollaborative = computed(
244→    () => this.gameMode() === "simple_collaborative",
245→  );
246→  protected readonly twoPlayerMode = computed(
247→    () => this.playerCountMode() === "two_player",
248→  );
249→  protected readonly practiceMode = computed(
250→    () => this.playerCountMode() === "practice",
251→  );
252→  protected readonly activeModeName = computed(() => {
253→    const mode = this.playerCountMode();
254→    return mode === "practice"
255→      ? "Practice (Solo)"
256→      : mode === "two_player"
257→        ? "2 Players"
258→        : "Full Team";
259→  });
260→
261→  protected readonly maxSlots = computed(() => {
262→    if (this.practiceMode()) return 1;
263→    if (this.twoPlayerMode()) return 2;
264→    const roles = this.scenarioRoles();
265→    return roles.length + (this.requiresGm() ? 1 : 0);
266→  });
267→
268→  protected readonly readinessPercent = computed(() => {
269→    const max = this.maxSlots();
270→    return max > 0 ? (this.participants().length / max) * 100 : 0;
271→  });
272→
273→  protected readonly canStart = computed(() => {
274→    const roles = this.scenarioRoles();
275→    if (!roles.length) return false;
276→    if (this.practiceMode()) return this.participants().length === 1;
277→    if (this.twoPlayerMode()) {
278→      const pRoles = this.participants().map((p) => p.role);
279→      return (
280→        this.participants().length === 2 &&
281→        pRoles.includes("decision_maker") &&
282→        pRoles.includes("all_advisors")
283→      );
284→    }
285→    return this.participants().length >= this.maxSlots();
286→  });
287→
288→  ngOnInit(): void {
289→    const params = this.route.snapshot.queryParams;
290→    const eId = Number(params["exerciseId"] ?? 0);
291→    const pId = String(params["participantId"] ?? "");
292→    const browse = params["browse"] === "true";
293→
294→    const rawPcm = params["playerCountMode"];
295→    const pcm: PlayerCountMode | undefined =
296→      rawPcm === "full" || rawPcm === "two_player" || rawPcm === "practice"
297→        ? rawPcm
298→        : undefined;
299→    if (pcm) {
300→      this.playerCountMode.set(pcm);
301→    }
302→
303→    if (browse) {
304→      this.browseMode.set(true);
305→      this.loadJoinableExercises();
306→    }
307→
308→    if (eId) {
309→      this.initExercise(eId, pId);
310→    }
311→  }
312→
313→  ngOnDestroy(): void {
314→    this.ws.disconnect();
315→    this.sub?.unsubscribe();
316→  }
317→
318→  protected selectExercise(lobby: JoinableExercise): void {
319→    this.ws.disconnect();
320→    this.sub?.unsubscribe();
321→    this.participantId.set("");
322→    this.participants.set([]);
323→    this.scenarioRoles.set([]);
324→    this.initExercise(lobby.exercise.id, "");
325→  }
326→
327→  protected onPlayerCountMode(mode: PlayerCountMode): void {
328→    this.playerCountMode.set(mode);
329→  }
330→
331→  protected onJoin(): void {
332→    const name = this.displayName().trim();
333→    if (!name) return;
334→    this.joining.set(true);
335→    this.api.join(this.exerciseId(), name, "player").subscribe({
336→      next: (p) => {
337→        this.participantId.set(p.id);
338→        this.joining.set(false);
339→      },
340→      error: () => this.joining.set(false),
341→    });
342→  }
343→
344→  protected onClaimRole(roleId: string): void {
345→    this.api
346→      .updateRole(this.exerciseId(), this.participantId(), roleId)
347→      .subscribe();
348→  }
349→
350→  protected onTwoPlayerRoleChange(ev: {
351→    targetId: string;
352→    roleId: string;
353→  }): void {
354→    this.api.updateRole(this.exerciseId(), ev.targetId, ev.roleId).subscribe();
355→  }
356→
357→  protected onLeave(): void {
358→    this.api.leave(this.exerciseId(), this.participantId()).subscribe({
359→      next: () => this.router.navigate(["/home"]),
360→      error: () => this.router.navigate(["/home"]),
361→    });
362→  }
363→
364→  protected onBackHome(): void {
365→    this.router.navigate(["/home"]);
366→  }
367→
368→  protected onStartExercise(): void {
369→    const me = this.participants().find((p) => p.id === this.participantId());
370→    const role = me?.role ?? "player";
371→    if (this.isSimpleCollaborative()) {
372→      this.router.navigate(["/player"], {
373→        queryParams: {
374→          exerciseId: this.exerciseId(),
375→          participantId: this.participantId(),
376→          role,
377→          gameMode: "simple_collaborative",
378→          practiceMode: this.practiceMode(),
379→        },
380→      });
381→      return;
382→    }
383→    const isGm = role === "game-master";
384→    this.router.navigate([isGm ? "/gm" : "/player"], {
385→      queryParams: {
386→        exerciseId: this.exerciseId(),
387→        participantId: this.participantId(),
388→        role,
389→      },
390→    });
391→  }
392→
393→  private initExercise(exerciseId: number, participantId: string): void {
394→    this.exerciseId.set(exerciseId);
395→    this.participantId.set(participantId);
396→    this.ws.connect(exerciseId, "player");
397→    this.sub = this.ws.messages$.subscribe((msg) => {
398→      if (msg.type === "waiting_room_update") {
399→        if (msg.participants) this.participants.set(msg.participants);
400→      }
401→    });
402→    this.api.listParticipants(exerciseId).subscribe({
403→      next: (res) => this.participants.set(res.participants),
404→    });
405→    this.loadScenarioRoles(exerciseId);
406→  }
407→
408→  private loadJoinableExercises(): void {
409→    this.http
410→      .get<
411→        JoinableExercise[]
412→      >(`${environment.apiBaseUrl}/api/exercises/joinable`)
413→      .subscribe({
414→        next: (data) => this.joinableExercises.set(data),
415→        error: () => this.joinableExercises.set([]),
416→      });
417→  }
418→
419→  private loadScenarioRoles(exerciseId: number): void {
420→    this.exerciseApi.get(exerciseId).subscribe({
421→      next: (exercise) => {
422→        this.gameMode.set(exercise.game_mode);
423→        this.requiresGm.set(exercise.game_mode === "classic");
424→        if (exercise.scenario_id) {
425→          this.scenarioApi.get(exercise.scenario_id).subscribe({
426→            next: (scenario) =>
427→              this.scenarioRoles.set(scenario.content?.roles ?? []),
428→          });
429→        }
430→      },
431→    });
432→  }
433→}
