  // Count requestAnimationFrame calls over 3 seconds
  const original = window.requestAnimationFrame;
  let count = 0;
  window.requestAnimationFrame = function(cb) {
    count++;
    return original.call(window, cb);
  };
  return new Promise(resolve => {
    setTimeout(() => {
      window.requestAnimationFrame = original;
      resolve({ rAF_calls_in_3s: count, fps: Math.round(count / 3) });
    }, 3000);
  });
}

() => {
  // Patch Zone or check if zoneless, and count CD cycles
  const ng = window.ng;
  if (!ng) return { error: 'ng not found' };

  // Check for zoneless
  const appRef = document.querySelector('[ng-version]');

  // Count how many times Angular checks components by monitoring DOM reads
  let cdCount = 0;
  const origGetAttribute = Element.prototype.getAttribute;
  Element.prototype.getAttribute = function(name) {
    if (name === 'ng-reflect-value' || name === 'ng-reflect-ng-if') cdCount++;
    return origGetAttribute.call(this, name);
  };

  return new Promise(resolve => {
    setTimeout(() => {
      Element.prototype.getAttribute = origGetAttribute;
      resolve({ angular_getAttribute_checks_in_2s: cdCount });
    }, 2000);
  });
}

