  1→import * as THREE from "three";
  2→import { createGlowTexture, waveY } from "./sea-signals";
  3→
  4→/** How often a new lightning bolt spawns (seconds). */
  5→export const LIGHTNING_INTERVAL = 0.8;
  6→
  7→/** How long the trail lingers after the head passes (seconds). */
  8→const TRAIL_FADE = 1.5;
  9→/** Slow global fade-out after trail is done (seconds). */
 10→const GLOBAL_FADE = 3.0;
 11→/** Speed: waypoints per second the head travels. */
 12→const TRAVEL_SPEED = 150;
 13→/** Max edges to walk along the wireframe. */
 14→const PATH_EDGES = 400;
 15→
 16→const BOLT_COLOR = 0xe84057; // hostile red — supply-chain attack
 17→const BOLT_COLOR_THREE = new THREE.Color(BOLT_COLOR);
 18→
 19→export interface Lightning {
 20→  birth: number;
 21→  line: THREE.Line;
 22→  head: THREE.Sprite;
 23→  headLight: THREE.PointLight;
 24→  waypoints: { x: number; z: number }[];
 25→}
 26→
 27→/** Grid-edge neighbours: 4 cardinal + 4 diagonal (follow wireframe lines). */
 28→const EDGE_DIRS: [number, number][] = [
 29→  [1, 0], [-1, 0], [0, 1], [0, -1],
 30→  [1, 1], [1, -1], [-1, 1], [-1, -1],
 31→];
 32→
 33→function tracePath(
 34→  positions: THREE.BufferAttribute,
 35→  cols: number,
 36→  rows: number,
 37→): { x: number; z: number }[] {
 38→  const path: { x: number; z: number }[] = [];
 39→  const visited = new Set<number>();
 40→  const key = (c: number, r: number) => r * cols + c;
 41→
 42→  // All 8 directions for varied bolt angles
 43→  const [headCol, headRow] = EDGE_DIRS[Math.floor(Math.random() * EDGE_DIRS.length)];
 44→
 45→  // Start at the opposite edge so the bolt traverses the sea
 46→  let col: number, row: number;
 47→  if (headCol > 0) col = 0;
 48→  else if (headCol < 0) col = cols - 1;
 49→  else col = Math.floor(Math.random() * cols);
 50→  if (headRow > 0) row = 0;
 51→  else if (headRow < 0) row = rows - 1;
 52→  else row = Math.floor(Math.random() * rows);
 53→
 54→  visited.add(key(col, row));
 55→  path.push({ x: positions.getX(key(col, row)), z: positions.getZ(key(col, row)) });
 56→
 57→  for (let i = 0; i < PATH_EDGES; i++) {
 58→    let moved = false;
 59→
 60→    if (Math.random() < 0.6) {
 61→      const fc = col + headCol;
 62→      const fr = row + headRow;
 63→      if (fc >= 0 && fc < cols && fr >= 0 && fr < rows && !visited.has(key(fc, fr))) {
 64→        col = fc;
 65→        row = fr;
 66→        moved = true;
 67→      }
 68→    }
 69→
 70→    if (!moved) {
 71→      const shuffled = [...EDGE_DIRS].sort(() => Math.random() - 0.5);
 72→      for (const [dc, dr] of shuffled) {
 73→        const nc = col + dc;
 74→        const nr = row + dr;
 75→        if (nc >= 0 && nc < cols && nr >= 0 && nr < rows && !visited.has(key(nc, nr))) {
 76→          col = nc;
 77→          row = nr;
 78→          moved = true;
 79→          break;
 80→        }
 81→      }
 82→    }
 83→
 84→    if (!moved) break;
 85→
 86→    visited.add(key(col, row));
 87→    const vi = key(col, row);
 88→    path.push({ x: positions.getX(vi), z: positions.getZ(vi) });
 89→
 90→    if ((headCol === 1 && col >= cols - 2) ||
 91→        (headCol === -1 && col <= 1) ||
 92→        (headRow === 1 && row >= rows - 2) ||
 93→        (headRow === -1 && row <= 1)) {
 94→      break;
 95→    }
 96→  }
 97→
 98→  return path;
 99→}
100→
101→let sharedGlow: THREE.Texture | null = null;
102→
103→export function createLightning(
104→  scene: THREE.Scene,
105→  planeGeo: THREE.PlaneGeometry,
106→  t: number,
107→): Lightning {
108→  const params = planeGeo.parameters;
109→  const cols = params.widthSegments + 1;
110→  const rows = params.heightSegments + 1;
111→  // eslint-disable-next-line @typescript-eslint/no-unsafe-type-assertion -- THREE.js geometry attributes are always BufferAttribute
112→  const positions = planeGeo.attributes["position"] as THREE.BufferAttribute;
113→  const waypoints = tracePath(positions, cols, rows);
114→  const n = waypoints.length;
115→
116→  // Position buffer
117→  const verts = new Float32Array(n * 3);
118→  // Per-vertex color buffer (for trail fade)
119→  const colors = new Float32Array(n * 3);
120→  for (let i = 0; i < n; i++) {
121→    const wp = waypoints[i];
122→    const off = i * 3;
123→    verts[off] = wp.x;
124→    verts[off + 1] = waveY(wp.x, wp.z, t);
125→    verts[off + 2] = wp.z;
126→    colors[off] = 0;
127→    colors[off + 1] = 0;
128→    colors[off + 2] = 0;
129→  }
130→
131→  const geo = new THREE.BufferGeometry();
132→  geo.setAttribute("position", new THREE.BufferAttribute(verts, 3));
133→  geo.setAttribute("color", new THREE.BufferAttribute(colors, 3));
134→
135→  const mat = new THREE.LineBasicMaterial({
136→    vertexColors: true,
137→    transparent: true,
138→    opacity: 1,
139→    blending: THREE.AdditiveBlending,
140→    depthWrite: false,
141→  });
142→
143→  const line = new THREE.Line(geo, mat);
144→  line.position.y = -0.3;
145→  scene.add(line);
146→
147→  // Travelling glow sprite
148→  if (!sharedGlow) sharedGlow = createGlowTexture();
149→  const spriteMat = new THREE.SpriteMaterial({
150→    map: sharedGlow,
151→    color: BOLT_COLOR,
152→    transparent: true,
153→    opacity: 0,
154→    blending: THREE.AdditiveBlending,
155→    depthWrite: false,
156→  });
157→  const head = new THREE.Sprite(spriteMat);
158→  head.scale.set(0.4, 0.4, 1);
159→  const wp0 = waypoints[0];
160→  head.position.set(wp0.x, waveY(wp0.x, wp0.z, t) - 0.3 + 0.15, wp0.z);
161→  scene.add(head);
162→
163→  // Point light follows the head
164→  const headLight = new THREE.PointLight(BOLT_COLOR, 0, 4);
165→  headLight.position.copy(head.position);
166→  scene.add(headLight);
167→
168→  return { birth: t, line, head, headLight, waypoints };
169→}
170→
171→/** Returns false when the bolt has fully faded. */
172→export function updateLightning(l: Lightning, t: number): boolean {
173→  const age = t - l.birth;
174→  const n = l.waypoints.length;
175→  const travelDuration = n / TRAVEL_SPEED;
176→  const totalLife = travelDuration + TRAIL_FADE + GLOBAL_FADE;
177→
178→  if (age > totalLife) return false;
179→
180→  // Global opacity: full during travel+trail, then slowly fade entire bolt
181→  const globalFadeStart = travelDuration + TRAIL_FADE;
182→  const globalOpacity = age > globalFadeStart
183→    ? Math.max(0, 1 - (age - globalFadeStart) / GLOBAL_FADE)
184→    : 1;
185→
186→  // Current head position (fractional index into waypoints)
187→  const headIdx = Math.min(age * TRAVEL_SPEED, n - 1);
188→  const headI = Math.floor(headIdx);
189→
190→  // Update positions to ride the wave
191→  // eslint-disable-next-line @typescript-eslint/no-unsafe-type-assertion -- THREE.js geometry attributes
192→  const posBuf = l.line.geometry.attributes["position"] as THREE.BufferAttribute;
193→  for (let i = 0; i < n; i++) {
194→    const wp = l.waypoints[i];
195→    const off = i * 3;
196→    posBuf.array[off] = wp.x;
197→    posBuf.array[off + 1] = waveY(wp.x, wp.z, t);
198→    posBuf.array[off + 2] = wp.z;
199→  }
200→  posBuf.needsUpdate = true;
201→
202→  // Update per-vertex colors: bright at head, fading trail behind
203→  // eslint-disable-next-line @typescript-eslint/no-unsafe-type-assertion -- THREE.js geometry attributes
204→  const colBuf = l.line.geometry.attributes["color"] as THREE.BufferAttribute;
205→  const r = BOLT_COLOR_THREE.r;
206→  const g = BOLT_COLOR_THREE.g;
207→  const b = BOLT_COLOR_THREE.b;
208→
209→  for (let i = 0; i < n; i++) {
210→    const off = i * 3;
211→    if (i > headI) {
212→      // Ahead of head — invisible
213→      colBuf.array[off] = 0;
214→      colBuf.array[off + 1] = 0;
215→      colBuf.array[off + 2] = 0;
216→    } else {
217→      // Behind head — fade based on distance from head
218→      const dist = headI - i;
219→      const timeSincePassed = dist / TRAVEL_SPEED;
220→      const fade = Math.max(0, 1 - timeSincePassed / TRAIL_FADE);
221→      const brightness = fade * globalOpacity;
222→      colBuf.array[off] = r * brightness;
223→      colBuf.array[off + 1] = g * brightness;
224→      colBuf.array[off + 2] = b * brightness;
225→    }
226→  }
227→  colBuf.needsUpdate = true;
228→
229→  // Move head sprite + light
230→  const wp = l.waypoints[headI];
231→  const hy = waveY(wp.x, wp.z, t) - 0.3 + 0.15;
232→  l.head.position.set(wp.x, hy, wp.z);
233→  l.headLight.position.set(wp.x, hy, wp.z);
234→
235→  // Head brightness: full while travelling, fade after done
236→  const headAlive = age < travelDuration;
237→  const headOpacity = (headAlive ? 0.4 : Math.max(0, 1 - (age - travelDuration) / TRAIL_FADE) * 0.2) * globalOpacity;
238→  (l.head.material as THREE.SpriteMaterial).opacity = headOpacity;
239→  l.headLight.intensity = (headAlive ? 2 : headOpacity * 2) * globalOpacity;
240→
241→  return true;
242→}
243→
244→export function disposeLightning(scene: THREE.Scene, l: Lightning): void {
245→  scene.remove(l.line);
246→  l.line.geometry.dispose();
247→  // eslint-disable-next-line @typescript-eslint/no-unsafe-type-assertion -- Line2 material is always Material
248→  (l.line.material as THREE.Material).dispose();
249→  scene.remove(l.head);
250→  (l.head.material as THREE.SpriteMaterial).dispose();
251→  scene.remove(l.headLight);
252→}
253→

