      raw.startsWith("oklch") ? 0x1ac5c5 : raw || 0x1ac5c5,
    );
  }

  constructor(private ngZone: NgZone) {
    afterNextRender(() => {
      this.initScene();
      this.ngZone.runOutsideAngular(() => this.animate(0));
