    this.camera.position.set(0, 6, 5);
    this.camera.lookAt(0, -0.4, -2);

    this.scene.add(new THREE.AmbientLight(0xffffff, 0.5));
    const dir = new THREE.DirectionalLight(0xffffff, 0.8);
