      if (!updateLightning(this.lightnings[i], t)) {
        disposeLightning(this.scene, this.lightnings[i]);
        this.lightnings.splice(i, 1);
      }
    }
  }

  // ── Core loop ──────────────────────────────────────────

  private handleResize(): void {
    const canvas = this.canvasRef().nativeElement;
