() => {
  // Count rAF calls over 3 seconds to verify 30fps cap
  const original = window.requestAnimationFrame;
  let count = 0;
  window.requestAnimationFrame = function(cb) {
    count++;
    return original.call(window, cb);
  };
  return new Promise(resolve => {
    setTimeout(() => {
      window.requestAnimationFrame = original;
      resolve({ rAF_calls_in_3s: count, effective_fps: Math.round(count / 3) });
    }, 3000);
  });
}

() => {
  // Count actual WebGL drawArrays/drawElements calls over 3 seconds
  const gl = document.querySelector('canvas')?.getContext('webgl2') || document.querySelector('canvas')?.getContext('webgl');
  if (!gl) return { error: 'no WebGL context' };

  const origDraw = gl.drawArrays.bind(gl);
  const origDrawEl = gl.drawElements.bind(gl);
  let drawCalls = 0;
  gl.drawArrays = function(...args) { drawCalls++; return origDraw(...args); };
  gl.drawElements = function(...args) { drawCalls++; return origDrawEl(...args); };

  return new Promise(resolve => {
    setTimeout(() => {
      gl.drawArrays = origDraw;
      gl.drawElements = origDrawEl;
      resolve({ draw_calls_in_3s: drawCalls, draws_per_frame_at_30fps: Math.round(drawCalls / 90) });
    }, 3000);
  });
}
